// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
}

import { IEventBus } from './types';

type EventCallback = (payload: unknown) => void;

export class EventBus implements IEventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event subscriber for event '${event}':`, error);
        }
      });
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)!.push(callback);
  }
}

import { User, IUserService } from '../types';
import * as crypto from 'node:crypto';

export class UserService implements IUserService {
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = crypto.randomUUID();
    const newUser: User = { id, ...input };
    this.users.set(id, newUser);
    return newUser;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User with ID ${id} not found`);
    }
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    const updatedUser = { ...user, ...input };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  delete(id: string): void {
    if (!this.users.delete(id)) {
      throw new Error(`User with ID ${id} not found`);
    }
  }
}

import { Project, IProjectService } from '../types';
import * as crypto from 'node:crypto';

export class ProjectService implements IProjectService {
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = crypto.randomUUID();
    const newProject: Project = { id, memberIds: [], ...input };
    this.projects.set(id, newProject);
    return newProject;
  }

  getById(id: string): Project {
    const project = this.projects.get(id);
    if (!project) {
      throw new Error(`Project with ID ${id} not found`);
    }
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const project = this.getById(id);
    const updatedProject = { ...project, ...input };
    this.projects.set(id, updatedProject);
    return updatedProject;
  }

  delete(id: string): void {
    if (!this.projects.delete(id)) {
      throw new Error(`Project with ID ${id} not found`);
    }
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.projects.set(projectId, project);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    const initialLength = project.memberIds.length;
    project.memberIds = project.memberIds.filter(id => id !== userId);
    if (project.memberIds.length === initialLength) {
        throw new Error(`User ${userId} is not a member of project ${projectId}`);
    }
    this.projects.set(projectId, project);
    return project;
  }
}

import { Task, TaskStatus, ITaskService, IEventBus, TaskAssignedPayload, TaskStatusChangedPayload } from '../types';
import * as crypto from 'node:crypto';

export class TaskService implements ITaskService {
  private tasks: Map<string, Task> = new Map();
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.eventBus = eventBus;
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = crypto.randomUUID();
    const newTask: Task = { id, status: "todo", assigneeId: null, ...input };
    this.tasks.set(id, newTask);
    return newTask;
  }

  getById(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task with ID ${id} not found`);
    }
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.getById(id);
    const updatedTask = { ...task, ...input };
    this.tasks.set(id, updatedTask);
    return updatedTask;
  }

  delete(id: string): void {
    if (!this.tasks.delete(id)) {
      throw new Error(`Task with ID ${id} not found`);
    }
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    if (task.assigneeId === assigneeId) {
      return task; // Already assigned to this user
    }
    const updatedTask = { ...task, assigneeId };
    this.tasks.set(taskId, updatedTask);

    // Publish event
    const payload: TaskAssignedPayload = {
      taskId: updatedTask.id,
      taskTitle: updatedTask.title,
      assigneeId: updatedTask.assigneeId,
    };
    this.eventBus.publish("task.assigned", payload);

    return updatedTask;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldStatus = task.status;

    if (oldStatus === newStatus) {
      return task;
    }

    // Enforce FORWARD_ONLY_STATUS rule
    const statusOrder: TaskStatus[] = ["todo", "in-progress", "done"];
    const oldStatusIndex = statusOrder.indexOf(oldStatus);
    const newStatusIndex = statusOrder.indexOf(newStatus);

    if (newStatusIndex !== oldStatusIndex + 1) {
      throw new Error(`Invalid status transition: cannot change task from '${oldStatus}' to '${newStatus}'. Status must move forward sequentially (todo -> in-progress -> done).`);
    }

    const updatedTask = { ...task, status: newStatus };
    this.tasks.set(taskId, updatedTask);

    // Publish event
    const payload: TaskStatusChangedPayload = {
      taskId: updatedTask.id,
      taskTitle: updatedTask.title,
      assigneeId: updatedTask.assigneeId,
      oldStatus: oldStatus,
      newStatus: newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return updatedTask;
  }
}

import { Comment, ICommentService, IEventBus, CommentAddedPayload, ITaskService, IUserService } from '../types';
import * as crypto from 'node:crypto';

export class CommentService implements ICommentService {
  private comments: Map<string, Comment> = new Map();
  private eventBus: IEventBus;
  private userService: IUserService;
  private taskService: ITaskService;

  constructor(eventBus: IEventBus, userService: IUserService, taskService: ITaskService) {
    this.eventBus = eventBus;
    this.userService = userService;
    this.taskService = taskService;
  }

  create(input: { taskId: string; authorId: string; body: string }): Comment {
    const id = crypto.randomUUID();
    const createdAt = new Date().toISOString();
    const newComment: Comment = { id, createdAt, ...input };
    this.comments.set(id, newComment);

    // To publish CommentAddedPayload, we need taskTitle and authorName.
    // Per architectural rules, services communicate via EventBus, but also
    // must implement interfaces exactly. To fulfill CommentAddedPayload,
    // we retrieve necessary info from other services via their interfaces
    // which are passed in the constructor, thus avoiding direct file imports.
    let taskTitle = 'Unknown Task';
    let authorName = 'Unknown Author';

    try {
      const task = this.taskService.getById(input.taskId);
      taskTitle = task.title;
    } catch (error) {
      console.warn(`Could not find task ${input.taskId} for comment event:`, error);
    }

    try {
      const author = this.userService.getById(input.authorId);
      authorName = author.name;
    } catch (error) {
      console.warn(`Could not find author ${input.authorId} for comment event:`, error);
    }

    const payload: CommentAddedPayload = {
      commentId: newComment.id,
      taskId: newComment.taskId,
      taskTitle: taskTitle,
      authorId: newComment.authorId,
      authorName: authorName,
    };
    this.eventBus.publish("comment.added", payload);

    return newComment;
  }

  getById(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) {
      throw new Error(`Comment with ID ${id} not found`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.delete(id)) {
      throw new Error(`Comment with ID ${id} not found`);
    }
  }
}

import { Notification, INotificationService, IEventBus, TaskAssignedPayload, TaskStatusChangedPayload, CommentAddedPayload, IUserService, ITaskService } from '../types';
import * as crypto from 'node:crypto';

export class NotificationService implements INotificationService {
  private notifications: Map<string, Notification> = new Map();
  private eventBus: IEventBus;
  private userService: IUserService;
  private taskService: ITaskService;

  constructor(eventBus: IEventBus, userService: IUserService, taskService: ITaskService) {
    this.eventBus = eventBus;
    this.userService = userService;
    this.taskService = taskService;
    this.setupEventSubscriptions();
  }

  private setupEventSubscriptions(): void {
    this.eventBus.subscribe("task.assigned", (payload: unknown) => {
      const p = payload as TaskAssignedPayload;
      if (p.assigneeId) {
        this.createNotification(p.assigneeId, `Task '${p.taskTitle}' assigned to you`);
      }
    });

    this.eventBus.subscribe("task.statusChanged", (payload: unknown) => {
      const p = payload as TaskStatusChangedPayload;
      if (p.assigneeId) {
        this.createNotification(p.assigneeId, `Task '${p.taskTitle}' status changed to ${p.newStatus}`);
      }
    });

    this.eventBus.subscribe("comment.added", (payload: unknown) => {
      const p = payload as CommentAddedPayload;
      try {
        const task = this.taskService.getById(p.taskId);
        if (task.assigneeId) {
          this.createNotification(task.assigneeId, `New comment on your task '${p.taskTitle}' by ${p.authorName}: ${p.body.substring(0, 50)}...`);
        }
      } catch (error) {
        console.error(`Error processing comment.added event for taskId ${p.taskId}:`, error);
      }
    });
  }

  private createNotification(userId: string, message: string): Notification {
    const id = crypto.randomUUID();
    const createdAt = new Date().toISOString();
    const newNotification: Notification = {
      id,
      userId,
      message,
      read: false,
      createdAt,
    };
    this.notifications.set(id, newNotification);
    return newNotification;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter(n => n.userId === userId);
  }

  markAsRead(notificationId: string): Notification {
    const notification = this.notifications.get(notificationId);
    if (!notification) {
      throw new Error(`Notification with ID ${notificationId} not found`);
    }
    const updatedNotification = { ...notification, read: true };
    this.notifications.set(notificationId, updatedNotification);
    return updatedNotification;
  }
}

import * as http from 'node:http';
import * as url from 'node:url';
import { 
  IUserService, 
  IProjectService, 
  ITaskService, 
  ICommentService, 
  INotificationService, 
  TaskStatus,
} from './types';

interface RouteHandler {
  (req: http.IncomingMessage, res: http.ServerResponse, params: Record<string, string>, query: Record<string, string>): Promise<void>;
}

interface Route {
  method: string;
  regex: RegExp;
  handler: RouteHandler;
  paramNames: string[];
}

export class ApiRouter {
  private routes: Route[] = [];
  private userService: IUserService;
  private projectService: IProjectService;
  private taskService: ITaskService;
  private commentService: ICommentService;
  private notificationService: INotificationService;

  constructor(
    userService: IUserService,
    projectService: IProjectService,
    taskService: ITaskService,
    commentService: ICommentService,
    notificationService: INotificationService
  ) {
    this.userService = userService;
    this.projectService = projectService;
    this.taskService = taskService;
    this.commentService = commentService;
    this.notificationService = notificationService;
    this.registerRoutes();
  }

  private registerRoute(method: string, path: string, handler: RouteHandler): void {
    const paramNames: string[] = [];
    const regexPath = path.replace(/\/:([a-zA-Z0-9_]+)/g, (_, paramName) => {
      paramNames.push(paramName);
      return '\/([a-zA-Z0-9_-]+)';
    });
    this.routes.push({
      method,
      regex: new RegExp(`^${regexPath}/?$`),
      handler,
      paramNames,
    });
  }

  private async parseBody(req: http.IncomingMessage): Promise<any> {
    return new Promise((resolve, reject) => {
      let body = '';
      req.on('data', chunk => {
        body += chunk.toString();
      });
      req.on('end', () => {
        if (body) {
          try {
            resolve(JSON.parse(body));
          } catch (error) {
            reject(new Error('Invalid JSON body'));
          }
        } else {
          resolve({});
        }
      });
      req.on('error', err => {
        reject(err);
      });
    });
  }

  public async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
    const parsedUrl = url.parse(req.url || '', true);
    const pathname = parsedUrl.pathname || '';
    const query = parsedUrl.query as Record<string, string>;

    res.setHeader('Content-Type', 'application/json');

    for (const route of this.routes) {
      const match = req.method === route.method && pathname.match(route.regex);
      if (match) {
        const params: Record<string, string> = {};
        route.paramNames.forEach((name, index) => {
          params[name] = match![index + 1];
        });

        try {
          const body = await this.parseBody(req);
          await route.handler(req, res, params, query);
        } catch (error: any) {
          if (error.message.includes('not found')) {
            res.statusCode = 404;
            res.end(JSON.stringify({ error: error.message }));
          } else if (error.message.includes('Invalid') || error.message.includes('cannot change task from')) {
            res.statusCode = 400;
            res.end(JSON.stringify({ error: error.message }));
          } else {
            res.statusCode = 500;
            res.end(JSON.stringify({ error: error.message }));
          }
        }
        return;
      }
    }

    res.statusCode = 404;
    res.end(JSON.stringify({ error: 'Not Found' }));
  }

  private registerRoutes(): void {
    // Users
    this.registerRoute('GET', '/users', async (req, res) => {
      const users = this.userService.getAll();
      res.end(JSON.stringify(users));
    });
    this.registerRoute('POST', '/users', async (req, res, params, query) => {
      const body = await this.parseBody(req);
      const user = this.userService.create(body);
      res.statusCode = 201;
      res.end(JSON.stringify(user));
    });
    this.registerRoute('GET', '/users/:id', async (req, res, params) => {
      const user = this.userService.getById(params.id);
      res.end(JSON.stringify(user));
    });
    this.registerRoute('PUT', '/users/:id', async (req, res, params) => {
      const body = await this.parseBody(req);
      const user = this.userService.update(params.id, body);
      res.end(JSON.stringify(user));
    });
    this.registerRoute('DELETE', '/users/:id', async (req, res, params) => {
      this.userService.delete(params.id);
      res.statusCode = 204;
      res.end();
    });

    // Projects
    this.registerRoute('GET', '/projects', async (req, res) => {
      const projects = this.projectService.getAll();
      res.end(JSON.stringify(projects));
    });
    this.registerRoute('POST', '/projects', async (req, res) => {
      const body = await this.parseBody(req);
      const project = this.projectService.create(body);
      res.statusCode = 201;
      res.end(JSON.stringify(project));
    });
    this.registerRoute('GET', '/projects/:id', async (req, res, params) => {
      const project = this.projectService.getById(params.id);
      res.end(JSON.stringify(project));
    });
    this.registerRoute('PUT', '/projects/:id', async (req, res, params) => {
      const body = await this.parseBody(req);
      const project = this.projectService.update(params.id, body);
      res.end(JSON.stringify(project));
    });
    this.registerRoute('DELETE', '/projects/:id', async (req, res, params) => {
      this.projectService.delete(params.id);
      res.statusCode = 204;
      res.end();
    });
    this.registerRoute('POST', '/projects/:id/members', async (req, res, params) => {
      const body = await this.parseBody(req);
      const project = this.projectService.addMember(params.id, body.userId);
      res.end(JSON.stringify(project));
    });
    this.registerRoute('DELETE', '/projects/:id/members', async (req, res, params) => {
      const body = await this.parseBody(req);
      const project = this.projectService.removeMember(params.id, body.userId);
      res.end(JSON.stringify(project));
    });

    // Tasks
    this.registerRoute('GET', '/tasks', async (req, res, params, query) => {
      if (query.projectId) {
        const tasks = this.taskService.getByProject(query.projectId);
        res.end(JSON.stringify(tasks));
      } else {
        res.statusCode = 400;
        res.end(JSON.stringify({ error: 'projectId query parameter is required' }));
      }
    });
    this.registerRoute('POST', '/tasks', async (req, res) => {
      const body = await this.parseBody(req);
      const task = this.taskService.create(body);
      res.statusCode = 201;
      res.end(JSON.stringify(task));
    });
    this.registerRoute('GET', '/tasks/:id', async (req, res, params) => {
      const task = this.taskService.getById(params.id);
      res.end(JSON.stringify(task));
    });
    this.registerRoute('PUT', '/tasks/:id', async (req, res, params) => {
      const body = await this.parseBody(req);
      const task = this.taskService.update(params.id, body);
      res.end(JSON.stringify(task));
    });
    this.registerRoute('DELETE', '/tasks/:id', async (req, res, params) => {
      this.taskService.delete(params.id);
      res.statusCode = 204;
      res.end();
    });
    this.registerRoute('PUT', '/tasks/:id/status', async (req, res, params) => {
      const body = await this.parseBody(req);
      const task = this.taskService.changeStatus(params.id, body.status as TaskStatus);
      res.end(JSON.stringify(task));
    });
    this.registerRoute('PUT', '/tasks/:id/assign', async (req, res, params) => {
      const body = await this.parseBody(req);
      const task = this.taskService.assign(params.id, body.assigneeId);
      res.end(JSON.stringify(task));
    });

    // Comments
    this.registerRoute('GET', '/comments', async (req, res, params, query) => {
      if (query.taskId) {
        const comments = this.commentService.getByTask(query.taskId);
        res.end(JSON.stringify(comments));
      } else {
        res.statusCode = 400;
        res.end(JSON.stringify({ error: 'taskId query parameter is required' }));
      }
    });
    this.registerRoute('POST', '/comments', async (req, res) => {
      const body = await this.parseBody(req);
      const comment = this.commentService.create(body);
      res.statusCode = 201;
      res.end(JSON.stringify(comment));
    });
    this.registerRoute('GET', '/comments/:id', async (req, res, params) => {
      const comment = this.commentService.getById(params.id);
      res.end(JSON.stringify(comment));
    });
    this.registerRoute('DELETE', '/comments/:id', async (req, res, params) => {
      this.commentService.delete(params.id);
      res.statusCode = 204;
      res.end();
    });

    // Notifications
    this.registerRoute('GET', '/notifications', async (req, res, params, query) => {
      if (query.userId) {
        const notifications = this.notificationService.getByUser(query.userId);
        res.end(JSON.stringify(notifications));
      } else {
        res.statusCode = 400;
        res.end(JSON.stringify({ error: 'userId query parameter is required' }));
      }
    });
    this.registerRoute('PUT', '/notifications/:id/read', async (req, res, params) => {
      const notification = this.notificationService.markAsRead(params.id);
      res.end(JSON.stringify(notification));
    });
  }
}

import * as http from 'node:http';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';
import { ApiRouter } from './router';

const PORT = 3000;

async function bootstrap() {
  const eventBus = new EventBus();

  // Instantiate services
  const userService = new UserService();
  const projectService = new ProjectService();
  const taskService = new TaskService(eventBus);
  // CommentService requires userService and taskService to create accurate payloads
  const commentService = new CommentService(eventBus, userService, taskService);
  // NotificationService requires userService and taskService for message content and assignee lookup
  const notificationService = new NotificationService(eventBus, userService, taskService);

  // Instantiate router with all services
  const router = new ApiRouter(
    userService,
    projectService,
    taskService,
    commentService,
    notificationService
  );

  const server = http.createServer((req, res) => {
    router.handleRequest(req, res);
  });

  server.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });

  // Keep server running for demo/testing purposes
  process.on('SIGINT', () => {
    console.log('Shutting down server...');
    server.close(() => {
      console.log('Server shut down.');
      process.exit(0);
    });
  });

  return { userService, projectService, taskService, commentService, notificationService, server };
}

